"""Build docs/HYPOTHESIS-CENSUS.md from the raw census records.

Usage:
    python scripts/census_build.py <raw-headlines> <raw-manuscript> <raw-preds> <out.md> [--rereview]

Inputs are the verbatim outputs of scripts/census_run.py over
docs/census/roots-headlines.txt, docs/census/roots-manuscript-names.txt and
docs/census/roots-preds.txt. The classification below is a *rule table*,
printed in the document it produces, so a reader can check every row against
the rule that placed it. Nothing here is inferred from text search: every
binder, field and conclusion comes from the elaborated declaration.

Round F (doc 70, C-1..C-7) changed four things relative to round E:
  * counting units are separate named quantities, and the legacy 1288/351
    accounting is bridged, not silently replaced;
  * a status is asserted only where a curated row asserts it; every other
    Prop row is `unreviewed`. Roles (a regex suggestion) and statuses (a
    reviewed judgement) are different columns;
  * fields are keyed by their DECLARING structure (an inherited field is one
    schema), and a second expansion level plus a frontier list replace the
    silent one-level cut;
  * every status names its evidence declarations, whose type hashes are read
    from HEADLINE-SNAPSHOT.md and recorded in docs/census/status-evidence.json;
    a moved hash marks the status stale until re-reviewed (`--rereview`).
"""
import re, sys, json, collections, pathlib
sys.stdout.reconfigure(encoding='utf-8', errors='replace')

# ------------------------------------------------------------------ parsing
def parse(path):
    recs = []; cur = None; header = {}
    for line in pathlib.Path(path).read_text(encoding='utf-8').splitlines():
        if line.startswith('CENSUS-HEAD '): header['head'] = line[12:].strip(); continue
        if line.startswith('CENSUS-TOOLCHAIN '): header['toolchain'] = line[17:].strip(); continue
        if line.startswith('CENSUS-CMD '): header['cmd'] = line[11:].strip(); continue
        if line.startswith('CENSUS-REQUESTED '): header['requested'] = int(line[17:].strip()); continue
        if line.startswith('CENSUS-DONE '): header['done'] = int(line[12:].strip()); continue
        if line.startswith('CENSUS-BEGIN '):
            cur = {'name': line[13:].strip(), 'binders': [], 'concl': '', 'kind': ''}
        elif line.startswith('CENSUS-END'):
            recs.append(cur); cur = None
        elif cur is None:
            continue
        elif line.startswith('KIND '):
            cur['kind'] = line[5:].strip()
        elif line.startswith('BINDER '):
            k, name, bi, isp, head, ty = [t.strip() for t in line[7:].split(' | ', 5)]
            cur['binders'].append({'k': int(k), 'name': name, 'bi': bi, 'isProp': isp == 'true',
                                   'head': head, 'type': ty, 'struct': None, 'fields': [],
                                   'unfold': None, 'frontier': []})
        elif line.startswith('EXPAND-STRUCT '):
            k, sn = [t.strip() for t in line[14:].split(' | ', 1)]
            cur['binders'][int(k) - 1]['struct'] = sn
        elif line.startswith('FIELD '):
            k, fn, isp, ty = [t.strip() for t in line[6:].split(' | ', 3)]
            cur['binders'][int(k) - 1]['fields'].append(
                {'qname': fn, 'name': fn.rsplit('.', 1)[-1], 'owner': fn.rsplit('.', 1)[0],
                 'isProp': isp == 'true', 'type': ty, 'unfold': None, 'struct': None, 'sub': []})
        elif line.startswith('FIELD-UNFOLD '):
            k, fn, u = [t.strip() for t in line[13:].split(' | ', 2)]
            for f in cur['binders'][int(k) - 1]['fields']:
                if f['qname'] == fn: f['unfold'] = u
        elif line.startswith('FIELD-STRUCT '):
            k, fn, sn = [t.strip() for t in line[13:].split(' | ', 2)]
            for f in cur['binders'][int(k) - 1]['fields']:
                if f['qname'] == fn: f['struct'] = sn
        elif line.startswith('FIELD2 '):
            k, path, fn, isp, ty = [t.strip() for t in line[7:].split(' | ', 4)]
            parent = path.rstrip(' >').strip()
            for f in cur['binders'][int(k) - 1]['fields']:
                if f['qname'] == parent:
                    f['sub'].append({'qname': fn, 'name': fn.rsplit('.', 1)[-1],
                                     'owner': fn.rsplit('.', 1)[0], 'isProp': isp == 'true', 'type': ty})
        elif line.startswith('FRONTIER '):
            k, fpath, reason = [t.strip() for t in line[9:].split(' | ', 2)]
            cur['binders'][int(k) - 1]['frontier'].append((fpath, reason))
        elif line.startswith('UNFOLD '):
            k, u = [t.strip() for t in line[7:].split(' | ', 1)]
            cur['binders'][int(k) - 1]['unfold'] = u
        elif line.startswith('CONCL '):
            cur['concl'] = line[6:].strip()
    if 'done' not in header or header.get('requested') != header.get('done') or len(recs) != header.get('requested'):
        raise SystemExit(f'FAIL: {path} is not a complete run (requested {header.get("requested")}, '
                         f'records {len(recs)}, done {header.get("done")})')
    return recs, header

def parse_preds(path):
    preds = {}; cur = None
    for raw in pathlib.Path(path).read_text(encoding='utf-8').splitlines():
        line = raw
        m = re.search(r'PRED-BEGIN\s+(\S+)', line)
        if m:
            cur = {'name': m.group(1), 'type': '', 'body': ''}; continue
        if 'PRED-END' in line and cur is not None:
            preds[cur['name']] = cur; cur = None; continue
        if cur is None: continue
        t = line.strip()
        if t.startswith('TYPE '): cur['type'] = t[5:]
        elif t.startswith('BODY '): cur['body'] = t[5:]
    return preds

