SIGN_SHAPE = re.compile(r'^(0 ≤ \S+|0 < \S+|\S+ < 1|\S+ ≤ 1|\S+ ∈ Sanctions\.I|\S+ ∈ Set\.(Icc|Ico|Ioc|Ioo) 0 1|\S+ ∈ Set\.Icc 0 \S+|\S+ ≤ \S+ - \S+|x0 ∈ Set\.Icc 0 1)$')
def role_of(name, ty, owner=None):
    # round AX: classify the content, not the projection binder. A field's
    # printed type opens with `∀ (self : <owner>), `, which names the owner;
    # the `Chord` rule below then fired on `ChordEconomy` for every field of
    # the chord economy, whatever the field said.
    ty = re.sub(r'^∀ \(self : [^)]*\), ', '', ty)
    # doc 70 A7 / doc 71 T1: a baseline field NAME on a CERTIFICATE is an
    # operator-row coefficient of that certificate, not the primitive
    # discount / payoff; on a FAMILY the `F_*` fields are the baseline
    # transition conditions restated for the family's own transition.
    if owner is not None and owner not in BASELINE_STRUCTS and owner not in FAMILY_STRUCTS and name in BASELINE_FIELDS:
        return 'certificate coefficient (operator row)', 'a coefficient of the certificate that shares a baseline field name'
    if owner is not None and owner not in BASELINE_STRUCTS and name in ('L_TS', 'L_ST'):
        return 'certificate coefficient (operator row)', 'a cross-row Lipschitz coefficient of the certificate'
    if owner is not None and owner in FAMILY_STRUCTS and name in BASELINE_FIELDS:
        return 'baseline environment', 'the family restates a baseline transition condition for its own `F`'
    for rx, role, note in ROLE_RULES:
        if re.search(rx, name) or re.search(rx, ty):
            return role, note
    return 'unclassified', 'no rule matched; read the type'

def scope_of(ty):
    """A heuristic reading of the quantifier prefix of a printed type."""
    if re.search(r'∀ \((V_T|V_S|V|W)[^)]*: [^)]*Carrier', ty) or 'carrier' in ty or 'Carrier' in ty:
        return 'all carrier members / pairs'
    if re.search(r'∀ [^,]*∈ Set\.Icc', ty) or re.search(r'∀ [^,]*∈ Sanctions\.I', ty):
        return 'all states / actions in a set'
    if ty.startswith('∀'):
        return 'universal (read the binder)'
    return 'single object / scalar'

