def display_key(t):
    # NOT alpha-normalisation: the printed type under the probe's fixed pp
    # options, with the leading `{p : Params}` / `(self : …)` binders and the
    # `self.` prefix removed so the same schema printed from two roots
    # deduplicates. Two binders that differ only in a bound-variable NAME
    # remain distinct keys.
    t = re.sub(r'∀ \{p : Sanctions\.AbstractGame\.Params\}[^,]*, ', '', t)
    t = re.sub(r'∀ \(self : [^)]*\), ', '', t)
    t = re.sub(r'\bself\.', '', t)
    return t.strip()

# ------------------------------------------------------------- evidence
def read_snapshot_evidence(path='HEADLINE-SNAPSHOT.md'):
    """name -> hash for every hashed row of the snapshot (headline, contract, evidence)."""
    out = {}
    for l in pathlib.Path(path).read_text(encoding='utf-8').splitlines():
        m = re.match(r'^\| `([^`]+)` \| `([0-9a-f]{64})` \|', l)
        if m: out[m.group(1)] = m.group(2)
    return out

def resolve_evidence(short, snap):
    hits = [n for n in snap if n == short or n.endswith('.' + short)]
    if len(hits) == 1: return hits[0]
    raise SystemExit(f'FAIL: evidence {short!r} resolves to {len(hits)} snapshot rows: {hits[:4]}')

# ------------------------------------------------------------------- build
def build(raw_h, raw_m, raw_p, out, roots_m_file, rereview=False):
    H, hdr_h = parse(raw_h); M, hdr_m = parse(raw_m); P = parse_preds(raw_p)
    if hdr_h.get('head') != hdr_m.get('head'):
        raise SystemExit('FAIL: the two raw files come from different commits')
    snap = read_snapshot_evidence()
    ev_path = pathlib.Path('docs/census/status-evidence.json')
    recorded = json.loads(ev_path.read_text(encoding='utf-8')) if ev_path.exists() else {}
    cited = set()
    for _, (_, _, evs) in STATUS_OVERRIDE.items(): cited |= set(evs)
    for row in SUBSTANTIVE: cited |= set(row[4])
    full = {sh: resolve_evidence(sh, snap) for sh in sorted(cited)}
    # A recorded hash for a declaration no status cites any more is not evidence
    # of anything: drop it, so the record is exactly the cited set (round Q1,
    # 2026-09-11 -- the round-P record of `plSigV_nonneg_of_closure` outlived
    # the field status that cited it and tripped gate 7 on its arity change).
    recorded = {fn: v for fn, v in recorded.items() if fn in set(full.values())}
    stale = {}
    for sh, fn in full.items():
        cur = snap[fn]
        if fn not in recorded or rereview:
            recorded[fn] = {'hash': cur, 'reviewed': hdr_h.get('head', '')[:12]}
        elif recorded[fn]['hash'] != cur:
            stale[sh] = (recorded[fn]['hash'][:12], cur[:12])
    ev_path.write_text(json.dumps(recorded, indent=1, sort_keys=True, ensure_ascii=False) + '\n', encoding='utf-8')
    def stale_mark(evs):
        s = [e for e in evs if e in stale]
        return (' **STALE** (' + ', '.join(f'`{e}`' for e in s) + ')') if s else ''

    labels = collections.defaultdict(list)
    for line in pathlib.Path(roots_m_file).read_text(encoding='utf-8').splitlines():
        if line.strip() and not line.startswith('#'):
            lab, dec = [t.strip() for t in line.split('|', 1)]
            labels[dec].append(lab)
    allrecs = {}
    for r in H + M:
        if r['name'] in allrecs and allrecs[r['name']] != r:
            raise SystemExit(f'FAIL: root {r["name"]} appears twice with different records')
        allrecs[r['name']] = r
    md = []
    A = md.append
    A('# Hypothesis census (compiler-derived)')
    A('')
    A('Generated by `scripts/census_run.py` + `scripts/census_build.py` from the')
    A('elaborated types of every headline row and every main-text result\'s backing')
    A('declaration. Each binder is listed with its type; structure-typed binders are')
    A('expanded through their fields two levels deep, with a frontier list for what')
    A('is not expanded; predicate-typed binders and fields are unfolded one level;')
    A('the substantive project predicates are printed once in the glossary.')
    A('')
    A('**Columns.** *Storage* is mechanical (baseline structure / family field /')
    A('certificate field / theorem binder). *Role* is a regex suggestion from the rule')
    A('table at the end, printed as a suggestion. *Scope* is a heuristic reading of the')
    A('quantifier prefix. *Status* is asserted only where a reviewed row asserts it')
    A('(the curated tables at the end); every other `Prop` row is **unreviewed**.')
    A('No status is inferred from a name.')
    A('')
    A(f'Source commit `{hdr_h.get("head", "?")[:12]}`, toolchain `{hdr_h.get("toolchain", "?")}`;')
    A('rendering `pp.fullNames true`, `pp.deepTerms true`, `pp.maxSteps 1000000`,')
    A('`pp.proofs false` (the same policy as the snapshot fence).')
    A('')
    # ---- counts (doc 70, C-2)
    roots = list(allrecs.values())
    n_bind = n_bind_prop = n_f1 = n_f1_prop = n_f2 = n_f2_prop = n_front = 0 ; n_prop_containers = 0
    legacy_raw = 0
    schema = {}          # owner-qualified field name or binder display key -> (kind, role)
    legacy_dedup = {}    # the round-E key (subclass-owned field name), for the bridge
    by_role = collections.Counter(); by_role_schema = collections.Counter()
    unreviewed = 0; reviewed = 0
    def status_for(name, role, qname=None, ty=''):
        ov = STATUS_OVERRIDE.get(qname) or STATUS_OVERRIDE.get(name)
        if ov: return ov[0], ov[1], ov[2]
        if SIGN_SHAPE.match(display_key(ty).strip().rsplit(' → ', 1)[-1].strip()):
            return 'domain (sign or range)', 'a sign, range or membership restriction on a scalar in the declared class; reviewed by parameter where it has an economic reading, otherwise a well-posedness or feasibility restriction', []
        if role in FIXED_STATUS: return FIXED_STATUS[role][0], FIXED_STATUS[role][1], []
        return STATUS_UNREVIEWED[0], STATUS_UNREVIEWED[1], None
    for r in roots:
        for b in r['binders']:
            n_bind += 1
            if b['isProp']: n_bind_prop += 1
            if b['isProp'] or b['struct'] or b['bi'] == 'explicit': legacy_raw += 1
            if b['struct'] and b['isProp']: n_prop_containers += 1
            if b['struct']:
                for f in b['fields']:
                    n_f1 += 1
                    if f['isProp']:
                        n_f1_prop += 1; legacy_raw += 1
                        role, _ = role_of(f['name'], f['type'], f['owner'])
                        by_role[role] += 1
                        if f['qname'] not in schema:
                            schema[f['qname']] = ('field', role); by_role_schema[role] += 1
                        legacy_dedup[b['struct'] + '.' + f['name']] = 1
                    for g in f['sub']:
                        n_f2 += 1
                        if g['isProp']:
                            n_f2_prop += 1
                            role, _ = role_of(g['name'], g['type'], g['owner'])
                            by_role[role] += 1
                            if g['qname'] not in schema:
                                schema[g['qname']] = ('field2', role); by_role_schema[role] += 1
                n_front += len(b['frontier'])
            elif b['isProp']:
                role, _ = role_of(b['name'], b['type'])
                by_role[role] += 1
                key = 'binder:' + display_key(b['type'])
                if key not in schema:
                    schema[key] = ('binder', role); by_role_schema[role] += 1
                legacy_dedup[key] = 1
    n_prop_occ = n_bind_prop + n_f1_prop + n_f2_prop
    n_status_bearing = n_prop_occ - n_prop_containers
    if sum(by_role.values()) != n_status_bearing:
        sys.exit(f'census_build: role table ({sum(by_role.values())}) != status-bearing occurrences ({n_status_bearing} = {n_prop_occ} logical - {n_prop_containers} containers)')
    A('## Counts')
    A('')
    A('Separate quantities, not one "hypothesis count" (doc 70, C-2):')
    A('')
    A('| quantity | count | definition |')
    A('|---|---|---|')
    A(f'| root declarations | {len(roots)} | distinct declarations probed ({len(H)} headline rows, {len(set(r["name"] for r in M))} manuscript-backing, overlap removed) |')
    A(f'| top-level parameter occurrences | {n_bind} | every binder of every root, implicit and instance binders included |')
    A(f'| top-level logical premises | {n_bind_prop} | the `Prop`-typed binders among them |')
    A(f'| expanded field occurrences, level 1 | {n_f1} (of which `Prop`: {n_f1_prop}) | every field of every structure-typed binder, per root |')
    A(f'| expanded field occurrences, level 2 | {n_f2} (of which `Prop`: {n_f2_prop}) | fields of a level-1 field whose type is a project structure |')
    A(f'| logical occurrences (premises + `Prop` fields, both levels) | {n_prop_occ} | every `Prop`-typed binder and field, containers included |')
    A(f'| expanded `Prop`-valued structure containers | {n_prop_containers} | `Prop`-typed binders whose type is a project structure: counted above, expanded into their fields, and given no role or status of their own |')
    A(f'| status-bearing occurrences | {n_status_bearing} | logical occurrences less the containers; the denominator of the role table and of the reviewed/unreviewed totals (asserted equal) |')
    A(f'| schema identities | {len(schema)} | distinct `Prop` fields by DECLARING structure (both levels) plus distinct `Prop` binders by display key |')
    A(f'| unexpanded frontier | {n_front} | field paths not expanded further, listed per root |')
    A('')
    A('**Bridge to the round-E numbers.** Round E reported 1288 "raw occurrences" and')
    A('351 "deduplicated contracts". The first counted `Prop`, structure-typed and')
    A('explicit binders plus level-1 `Prop` fields; on this run that rule gives')
    A(f'{legacy_raw} (the root set changed in round F: see the manuscript roots table).')
    A('Its role table summed to 1173 because structure-typed and data binders received')
    A('no role; the role table below sums to the status-bearing count (logical')
    A('occurrences less the expanded `Prop`-valued containers), which the builder asserts.')
    A(f'The second keyed inherited fields under the subclass that inherited them, so one')
    A(f'schema counted twice; on this run that rule gives {len(legacy_dedup)}, against')
    A(f'{len(schema)} schema identities keyed by the declaring structure (and including')
    A('level 2). The display key is the printed type under fixed `pp` options with the')
    A('`self`/`p` binders stripped; it is **not** alpha-normalisation — two binders that')
    A('differ only in a bound-variable name are two keys.')
    A('')
    A('| role (suggested) | logical occurrences | schema identities |')
    A('|---|---|---|')
    for role in sorted(by_role, key=lambda r: -by_role[r]):
        A(f'| {role} | {by_role[role]} | {by_role_schema[role]} |')
    A(f'| **total** | **{sum(by_role.values())}** | **{sum(by_role_schema.values())}** |')
    A('')
    # ---- manuscript roots table
    A('## Manuscript roots and their backing declarations')
    A('')
    A('| label | backing declaration(s) | probed |')
    A('|---|---|---|')
    lab2decs = collections.defaultdict(list)
    for dec, labs in labels.items():
        for l in labs: lab2decs[l].append(dec)
    for lab in lab2decs:
        decs = lab2decs[lab]
        ok = all(sum(1 for n in allrecs if n == d or n.endswith('.' + d)) == 1 for d in decs)
        A(f'| `{lab}` | ' + ', '.join(f'`{d}`' for d in decs) + f' | {"yes" if ok else "**missing or ambiguous**"} |')
    A('')
    A('The four assumption blocks of the model section are carried by certificate')
    A('fields rather than by free declarations: `ass:sender` by')
    A('`SenderPersistencePackage.sender_IDO_after_target_policy`, `ass:target` by the')
    A('Target chord fields of the persistence certificates, `ass:concavity` (stage')
    A('strong concavity in `s`) by the placable family\'s `hCurv`/`q`, from which')
    A('`ValueClass2.sender_unique_on` is *derived* on that family (stage A3 is not')
    A('itself dynamic argmax uniqueness), and `ass:flip` by the tipping thresholds of')
    A('`prop:tipping`.')
    A('')
    # ---- manuscript match
    A('## Manuscript match')
    A('')
    A('Relation vocabulary (doc 70, C-5): **exact statement** — one declaration states')
    A('the result as displayed; **valid specialization** — the declaration is more')
    A('general and the manuscript instance is a substitution; **proved composition** —')
    A('several declarations carry the conjuncts, listed clause by clause; **incomplete')
    A('mapping** / **unreviewed** — not yet checked at clause level. Every relation is a')
    A('recorded judgement against the pinned statements, not a mechanical comparison.')
    A('')
    A('| label | relation | clauses → declarations | note |')
    A('|---|---|---|---|')
    for lab, (rel, clauses, note) in MANUSCRIPT_MATCH.items():
        cl = '; '.join(f'{c}: `{d}`' for c, d in clauses)
        A(f'| `{lab}` | {rel} | {cl} | {note} |')
    A('')
    # ---- substantive contracts
    A('## Substantive contracts: status against the baseline, ranked')
    A('')
    A('The hypotheses a referee will ask about, with what the tree proves, refutes')
    A('or leaves open about deriving them from the baseline primitives. "Open"')
    A('means neither a proof nor a refutation exists in the tree. Each row names its')
    A('evidence declarations; a row is marked stale when an evidence type hash has')
    A('moved since the status was reviewed (`docs/census/status-evidence.json`).')
    A('')
    A('| # | contract | where | status | evidence / route |')
    A('|---|---|---|---|---|')
    for i, (c, w, st, ev, evs) in enumerate(SUBSTANTIVE, 1):
        A(f'| {i} | {c} | {w} | {st}{stale_mark(evs)} | {ev} |')
    A('')
    if stale:
        A('**Stale evidence on this run:**')
        A('')
        for sh, (old, new) in sorted(stale.items()):
            A(f'- `{sh}`: reviewed against `{old}…`, now `{new}…` — re-review and run with `--rereview`')
        A('')
    # ---- per-root records
    def emit_root(r):
        nonlocal unreviewed, reviewed
        labs = [l for d, ls in labels.items() for l in ls if r['name'] == d or r['name'].endswith('.' + d)]
        A(f'### `{r["name"]}`')
        A('')
        if labs: A('Manuscript: ' + ', '.join(f'`{l}`' for l in sorted(set(labs))))
        A('')
        A('| # | binder | kind | type | storage | role (suggested) | scope (heuristic) | status |')
        A('|---|---|---|---|---|---|---|---|')
        for b in r['binders']:
            role, _ = role_of(b['name'], b['type'])
            if b['struct']:
                role = 'structure binder (expanded below)'; st = '—'
            elif b['isProp']:
                s0, _, evs = status_for(b['name'], role, r['name'] + '.' + b['name'], b['type'])
                st = s0 + (stale_mark(evs) if evs else '')
                if s0 == 'unreviewed': unreviewed += 1
                else: reviewed += 1
            else:
                st = 'data'
            nm = b['name'] if not b['name'].startswith('a._@') else '(anonymous)'
            ty = b['type'].replace('|', '\\|')
            if len(ty) > 400: ty = ty[:400] + ' …'
            A(f'| {b["k"]} | `{nm}` | {b["bi"]} | `{ty}` | {storage_of(None, True)} | {role} | {scope_of(b["type"]) if b["isProp"] else "—"} | {st} |')
        A('')
        for b in r['binders']:
            if b['struct'] and b['fields']:
                A(f'Expansion of binder {b["k"]}, `{b["struct"]}` (fields by declaring structure):')
                A('')
                A('| field | Prop? | type | storage | role (suggested) | scope (heuristic) | status | note |')
