    A('')
    A('Reviewed statuses by name (with their evidence declarations):')
    A('')
    A('| name | status | evidence |')
    A('|---|---|---|')
    for nm, (st, ev, evs) in STATUS_OVERRIDE.items():
        A(f'| `{nm}` | {st}{stale_mark(evs)} | {ev} |')
